#include <stdio.h>

/* teste do desafio sua-primeira-janela — counter_protocol (03-tdd 3.9.3).
   Aqui o aluno escreveu a funcao INTEIRA; o teste a chama e compara a
   janela. A captura do stdout acontece DENTRO do teste: freopen para o
   arquivo temporario, chamada da funcao, leitura do arquivo de volta. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void tela(void);

SM_TEST(a_janela_completa) {
    /* captura: o stdout vira o arquivo sm_saida.tmp */
    freopen("sm_saida.tmp", "w", stdout);
    tela();
    fflush(stdout);

    FILE *f = fopen("sm_saida.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a borda de cima", linha, "+------------------+\n",
              "a janela comeca pela borda de cima");
    fgets(linha, 80, f);
    checa_str("o conteudo da janela", linha, "| oi, sou a tela!  |\n",
              "entre as bordas vem a mensagem da tela");
    fgets(linha, 80, f);
    checa_str("a borda de baixo", linha, "+------------------+\n",
              "a janela fecha com a mesma borda de cima");
    fclose(f);
}

